 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)

    def bands(n, is_sep):
        result, start = [], 0
        for i in range(n):
            if is_sep(i):
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    hr = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    vc = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != bg]
    # A monochrome line in the dominant background is also a separator when
    # it is an explicit full-width/full-height divider (e.g. color 0).
    if not hr:
        hr = [r for r in range(h) if len(set(grid[r])) == 1]
    if not vc:
        vc = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    rb = bands(h, lambda r: r in hr)
    cb = bands(w, lambda c: c in vc)

    # Choose the richest tile as the pattern, and repeat its non-background
    # cells into all tiles of the same dimensions. Separator lines stay intact.
    tiles = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            score = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            tiles.append((score, r0, r1, c0, c1))
    if not tiles:
        return out
    _, sr0, sr1, sc0, sc1 = max(tiles)
    sh, sw = sr1 - sr0, sc1 - sc0
    for r0, r1 in rb:
        for c0, c1 in cb:
            if r1-r0 != sh or c1-c0 != sw or (r0 == sr0 and c0 == sc0):
                continue
            for dr in range(sh):
                for dc in range(sw):
                    v = grid[sr0+dr][sc0+dc]
                    if v != bg:
                        out[r0+dr][c0+dc] = v
    return out
